434→	if err := json.Unmarshal(data, &settings); err != nil {
435→		t.Fatalf("parse settings: %v", err)
436→	}
437→	for k, v := range extra {
438→		settings[k] = v
439→	}
440→	out, err := json.MarshalIndent(settings, "", "  ")
441→	if err != nil {
442→		t.Fatalf("marshal settings: %v", err)
443→	}
444→	if err := os.WriteFile(path, out, 0o644); err != nil {
445→		t.Fatalf("write settings: %v", err)
446→	}
447→}
