449→// Git runs a git command in the given directory and fails the test if it
450→// returns a non-zero exit code.
451→func Git(t *testing.T, dir string, args ...string) {
452→	t.Helper()
453→
454→	cmd := exec.Command("git", args...)
455→	if dir != "" {
456→		cmd.Dir = dir
457→	}
458→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
459→
